&lt;li&gt;&lt;span data-ccp-parastyle=&quot;List Bullet&quot;&gt;Experience &lt;/span&gt;&lt;span data-ccp-parastyle=&quot;List Bullet&quot;&gt;operating&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;List Bullet&quot;&gt;&amp;nbsp;at scale in a fast-growing, multi-country environment&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
